{
  "technical_and_design_decisions": [
    "Use Spring Framework 6.0+ with Java 17 as the baseline for all module development.",
    "Implement the native WebSocket sink using Spring's built-in WebSocket support to ensure full-duplex communication over a single TCP connection.",
    "Utilize Bamboo for Windows OS CI and EC2 for Linux-based CI, configuring both to use the Gradle wrapper (./gradlew) directly instead of Artifactory Gradle tasks.",
    "Manage shared dependencies by placing common jars in the xd/lib folder, while bundling version-specific jars directly within custom modules to avoid classloader conflicts.",
    "Configure SonarQube to automatically notify committers of PMD/Sonar violations."
  ],
  "assumptions": [
    "Access to HDFS, Bamboo, EC2, and Windows environments is already provisioned and available.",
    "The development team has prior experience with Spring Framework, Gradle, and CI/CD tools.",
    "The existing build system supports the creation of uber-jars (e.g., via Gradle Shadow plugin).",
    "SonarQube and PMD are already integrated into the CI pipeline but require configuration updates for notifications and violation fixes.",
    "Necessary services like Redis and RabbitMQ can be easily installed on the Windows CI environment via PowerShell."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Custom Module Documentation",
      "activity_description": "Create and publish documentation detailing recommended standards and patterns for building custom modules based on the Spring Framework.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A2",
      "activity_name": "HDFS Hosting for Custom Module",
      "activity_description": "Configure the build process to package the custom module as an uber-jar and host it in HDFS for deployment to newly arriving containers.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A3",
      "activity_name": "Native WebSocket Sink Implementation",
      "activity_description": "Develop and integrate a native WebSocket sink to enable full-duplex communication channels over a single TCP connection.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A4",
      "activity_name": "CI Options Research and npm-cache Integration",
      "activity_description": "Research CI options to improve build stability, specifically evaluating and integrating npm-cache to cache previously installed dependencies.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A5",
      "activity_name": "EC2 CI Infrastructure Improvements",
      "activity_description": "Update EC2 CI infrastructure by enabling distributed JVM tests, switching to ./gradlew command task, testing with embedded Hadoop off, and turning on maxParallelForks.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A6",
      "activity_name": "Log Investigation and Sonar/PMD Fixes",
      "activity_description": "Investigate the increase in WARN logs, fix PMD/Sonar violations, and configure Sonar to notify the committer of any violations.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A7",
      "activity_name": "Windows OS CI Infrastructure Setup",
      "activity_description": "Set up CI infrastructure on the Bamboo environment running Windows OS, including gaining PowerShell access, setting up services (Redis, Rabbit, etc.), and kicking off the CI task.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A8",
      "activity_name": "Shared Dependency Location Configuration",
      "activity_description": "Establish a common shared location (xd/lib folder) for dependent jars required by multiple custom modules, and document the classloader workaround for version conflicts.",
      "most_likely_effort": 8
    }
  ],
  "reported_total": {
    "most_likely_effort": 118
  }
}

